from harness import *

async def main():
 async with async_playwright() as pw:
  browser=await pw.chromium.launch(executable_path=BROWSER_EXECUTABLE,headless=True,args=TEST_BROWSER_ARGS)
  ctx,p=await boot(browser)
  await p.click('#starterButton');await p.wait_for_function("Object.keys(CorpusLab.state.corpus.entries).length===2 && !CorpusLab.state.job && CorpusLab.state.panes.A.raw && CorpusLab.state.panes.B.raw")
  check('Starter button loads two real clips with prepared automatic drafts',await p.evaluate('Object.values(CorpusLab.state.corpus.entries).every(e=>e.project.frames.length===49&&e.project.passes.length>0)'))
  check('Inherited 35-clip corpus index is retained, not all media rebundled',await p.evaluate('CorpusLab.state.corpus.inheritedCorpora[0].manifest.panels.length===35&&Object.keys(CorpusLab.state.corpus.media).length===2'))
  check('Shipped starter contains no human verification',await p.evaluate('Object.values(CorpusLab.state.corpus.entries).every(e=>!e.reviews.length&&!e.project.locks.length)'))
  check('Background removal produces transparency in both panes',await p.evaluate('Object.values(CorpusLab.state.panes).every(p=>p.clean.transparent>.5)'),await p.evaluate('Object.values(CorpusLab.state.panes).map(p=>p.clean.transparent)'))
  check('Raw source pixels remain opaque and separate from clean output',await p.evaluate('(()=>{const p=CorpusLab.state.panes.A;return p.raw.data[3]===255&&p.clean.image.data[3]===0&&p.raw.data!==p.clean.image.data;})()'))
  await p.screenshot(path=str(ROOT/'preview.png'))
  a=await p.evaluate('CorpusLab.state.panes.A.entryId');b=await p.evaluate('CorpusLab.state.panes.B.entryId')
  await p.select_option('#group','leftArm');await p.click('[data-tab="anatomy"]')
  # Real pointer joint editing in source-coordinate transform.
