  box=await p.locator('#canvasA').bounding_box();await p.mouse.move(box['x']+pt['x'],box['y']+pt['y']);await p.mouse.down();await p.mouse.move(box['x']+pt['x']+14,box['y']+pt['y']-9,steps=5);await p.mouse.up()
  check('Dragging a joint creates an exact manual pin',await p.evaluate("!!CorpusLab.state.corpus.entries[CorpusLab.state.panes.A.entryId].project.edits[0]?.['elbow.left']"))
  moved=await p.evaluate("Universal.resolve(CorpusLab.state.corpus.entries[CorpusLab.state.panes.A.entryId].project,0).points['elbow.left'].x")
  check('Drag accounts for viewport scale',abs(moved-(pt['oldX']+14/pt['scale']))<1)
  await p.click('#undo');check('Undo removes the new pin',await p.evaluate("!CorpusLab.state.corpus.entries[CorpusLab.state.panes.A.entryId].project.edits[0]?.['elbow.left']"))
  await p.click('#redo');check('Redo restores the pin',await p.evaluate("!!CorpusLab.state.corpus.entries[CorpusLab.state.panes.A.entryId].project.edits[0]?.['elbow.left']"))
  # Scope visibility, then exact restoration via undo.
